import React, { useState, useEffect } from 'react';
import { useNavigate } from 'react-router-dom';
import axios from 'axios';
import AddProductPage from './AddProductPage';
import './CSS/SellerDashboard.css';

function SellerDashboard() {
  const navigate = useNavigate();
  const [activeTab, setActiveTab] = useState('overview'); // 'overview' or 'addProduct'
  const [sellerProducts, setSellerProducts] = useState([]);
  const [loading, setLoading] = useState(true);

  // Fetch products listed by sellers
  const fetchSellerProducts = async () => {
    try {
      setLoading(true);
      const response = await axios.get('http://localhost:4000/api/seller/products');
      if (Array.isArray(response.data)) {
        setSellerProducts(response.data);
      } else if (response.data && Array.isArray(response.data.products)) {
        setSellerProducts(response.data.products);
      } else {
        setSellerProducts([]);
      }
    } catch (err) {
      console.error('Error fetching seller products:', err);
      setSellerProducts([]);
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    fetchSellerProducts();
  }, [activeTab]);

  const handleDeleteProduct = async (productId) => {
    if (!window.confirm("Are you sure you want to delete this product?")) return;
    try {
      await axios.delete(`http://localhost:4000/api/seller/products/${productId}`);
      alert("Product deleted successfully");
      fetchSellerProducts();
    } catch (err) {
      console.error('Error deleting product:', err);
      alert("Failed to delete product");
    }
  };

  const resolveImageSrc = (rawImage) => {
    if (!rawImage) return 'https://via.placeholder.com/150';
    const cleanPath = String(rawImage).replace(/\\/g, '/');
    if (cleanPath.startsWith('http://') || cleanPath.startsWith('https://')) {
      return cleanPath;
    } else if (cleanPath.startsWith('/uploads')) {
      return `http://localhost:4000${cleanPath}`;
    } else if (cleanPath.startsWith('uploads')) {
      return `http://localhost:4000/${cleanPath}`;
    } else {
      return `http://localhost:4000/uploads/${cleanPath}`;
    }
  };

  return (
    <div className="seller-dashboard-layout" style={{ display: 'flex', minHeight: '100vh', backgroundColor: '#f8fafc' }}>
      
      {/* Seller Sidebar */}
      <div className="seller-sidebar" style={{ width: '260px', backgroundColor: '#130352', color: '#fff', padding: '25px 20px', display: 'flex', flexDirection: 'column', gap: '15px' }}>
        <h2 style={{ fontSize: '20px', fontWeight: '800', marginBottom: '20px', letterSpacing: '0.5px' }}>
          Seller Panel
        </h2>
        
        <button 
          onClick={() => setActiveTab('overview')}
          style={{
            background: activeTab === 'overview' ? 'rgba(255,255,255,0.15)' : 'transparent',
            border: 'none',
            color: '#fff',
            padding: '12px 16px',
            textAlign: 'left',
            borderRadius: '8px',
            fontWeight: '600',
            cursor: 'pointer',
            fontSize: '14px'
          }}
        >
          <i className="fa-solid fa-chart-line" style={{ marginRight: '10px' }}></i> Dashboard Overview
        </button>

        <button 
          onClick={() => setActiveTab('addProduct')}
          style={{
            background: activeTab === 'addProduct' ? 'rgba(255,255,255,0.15)' : 'transparent',
            border: 'none',
            color: '#fff',
            padding: '12px 16px',
            textAlign: 'left',
            borderRadius: '8px',
            fontWeight: '600',
            cursor: 'pointer',
            fontSize: '14px'
          }}
        >
          <i className="fa-solid fa-plus-circle" style={{ marginRight: '10px' }}></i> Add New Product
        </button>

        <button 
          onClick={() => navigate('/')}
          style={{
            marginTop: 'auto',
            background: 'none',
            border: '1px solid rgba(255,255,255,0.3)',
            color: '#fff',
            padding: '10px',
            borderRadius: '8px',
            cursor: 'pointer',
            fontWeight: '600'
          }}
        >
          Back to Store Home
        </button>
      </div>

      {/* Main Content Area */}
      <div className="seller-main-content" style={{ flex: 1, padding: '35px', overflowY: 'auto' }}>
        
        {activeTab === 'addProduct' ? (
          // Renders your separate AddProductPage component directly inside the dashboard
          <AddProductPage />
        ) : (
          <div>
            <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: '25px' }}>
              <div>
                <h1 style={{ fontSize: '24px', fontWeight: '800', color: '#0f172a', margin: 0 }}>Your Listed Products</h1>
                <p style={{ color: '#64748b', fontSize: '14px', margin: '4px 0 0 0' }}>Manage your inventory, pricing, and multi-image listings.</p>
              </div>
              <button 
                onClick={() => setActiveTab('addProduct')}
                style={{
                  backgroundColor: '#130352',
                  color: '#fff',
                  border: 'none',
                  borderRadius: '8px',
                  padding: '12px 20px',
                  fontWeight: 'bold',
                  fontSize: '14px',
                  cursor: 'pointer',
                  boxShadow: '0 4px 12px rgba(19, 3, 82, 0.2)'
                }}
              >
                + Add New Product
              </button>
            </div>

            {loading ? (
              <p style={{ color: '#64748b' }}>Loading your products...</p>
            ) : sellerProducts.length === 0 ? (
              <div style={{ textAlign: 'center', padding: '60px', backgroundColor: '#fff', borderRadius: '12px', border: '1px solid #e2e8f0' }}>
                <h3 style={{ color: '#475569', marginBottom: '10px' }}>No products listed yet</h3>
                <p style={{ color: '#94a3b8', fontSize: '14px', marginBottom: '20px' }}>Start selling by adding your first product with up to 10 images.</p>
                <button 
                  onClick={() => setActiveTab('addProduct')}
                  style={{ backgroundColor: '#130352', color: '#fff', border: 'none', padding: '10px 20px', borderRadius: '8px', fontWeight: 'bold', cursor: 'pointer' }}
                >
                  Create Product
                </button>
              </div>
            ) : (
              <div style={{ display: 'grid', gridTemplateColumns: 'repeat(auto-fill, minmax(260px, 1fr))', gap: '20px' }}>
                {sellerProducts.map((prod) => {
                  const prodId = prod._id || prod.id;
                  const firstImg = prod.images?.[0] || prod.imageUrl || prod.image;
                  const imgSrc = resolveImageSrc(firstImg);

                  return (
                    <div key={prodId} style={{ backgroundColor: '#fff', borderRadius: '12px', padding: '16px', border: '1px solid #e2e8f0', boxShadow: '0 2px 4px rgba(0,0,0,0.02)', display: 'flex', flexDirection: 'column', justifyContent: 'space-between' }}>
                      <div>
                        <div style={{ width: '100%', height: '180px', backgroundColor: '#f8fafc', borderRadius: '8px', overflow: 'hidden', display: 'flex', alignItems: 'center', justifyContent: 'center', marginBottom: '12px', border: '1px solid #f1f5f9' }}>
                          <img src={imgSrc} alt={prod.title || prod.name} style={{ maxHeight: '100%', maxWidth: '100%', objectFit: 'contain' }} />
                        </div>
                        <span style={{ fontSize: '11px', fontWeight: 'bold', color: '#64748b', textTransform: 'uppercase' }}>{prod.category}</span>
                        <h4 style={{ margin: '4px 0 8px 0', fontSize: '15px', fontWeight: '700', color: '#0f172a', whiteSpace: 'nowrap', overflow: 'hidden', textOverflow: 'ellipsis' }}>
                          {prod.title || prod.name}
                        </h4>
                        <div style={{ display: 'flex', alignItems: 'baseline', gap: '8px', marginBottom: '12px' }}>
                          <span style={{ fontSize: '18px', fontWeight: '800', color: '#130352' }}>${prod.price}</span>
                          {prod.originalPrice && <span style={{ fontSize: '13px', color: '#94a3b8', textDecoration: 'line-through' }}>${prod.originalPrice}</span>}
                        </div>
                        <div style={{ fontSize: '12px', color: '#475569', marginBottom: '10px' }}>
                          Images uploaded: <b>{prod.images?.length || 1}</b> / 10
                        </div>
                      </div>

                      <button 
                        onClick={() => handleDeleteProduct(prodId)}
                        style={{
                          width: '100%',
                          backgroundColor: '#fef2f2',
                          color: '#ef4444',
                          border: '1px solid #fecaca',
                          borderRadius: '6px',
                          padding: '8px',
                          fontWeight: 'bold',
                          fontSize: '13px',
                          cursor: 'pointer'
                        }}
                      >
                        Delete Product
                      </button>
                    </div>
                  );
                })}
              </div>
            )}
          </div>
        )}

      </div>
    </div>
  );
}

export default SellerDashboard;
